import { useId } from 'react';
import { cn } from '@/lib/cn';

/* Geometry generated by brand/src/build_logo.js (see brand/logo/grta-mark.svg). */
const CELLS = { G: [14, 14], R: [52, 14], T: [14, 52], A: [52, 52] } as const;
const PATHS = {
  G: 'M43.75 12 V18.25 H27.25 Q18.25 18.25 18.25 27.25 V34.75 Q18.25 43.75 27.25 43.75 H43.75 V31 H33',
  R: 'M56.25 50 V18.25 H72.75 Q81.75 18.25 81.75 26.25 V25 Q81.75 33.5 72.75 33.5 H56.25 M72 33.5 L90 52',
  T: 'M12 56.25 H50 M31 56.25 V88',
  A: 'M56.25 88 V65.25 Q56.25 56.25 65.25 56.25 H72.75 Q81.75 56.25 81.75 65.25 V88 M56.25 73 H81.75',
};

type MarkProps = {
  size?: number;
  className?: string;
  /** Block fill. Defaults to the ink block that stays dark in both themes. */
  block?: string | null;
  letters?: string;
  /** Animate a thread of light through the gutters (loader / hero intro). */
  living?: boolean;
  title?: string;
};

export function Mark({ size = 40, className, block = 'var(--mark-block, var(--c-ink))', letters = 'var(--c-ember)', living = false, title = 'GRTA' }: MarkProps) {
  const id = useId().replace(/:/g, '');
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" role="img" aria-label={title} className={cn('shrink-0', className)}>
      <defs>
        {Object.entries(CELLS).map(([k, [x, y]]) => (
          <clipPath key={k} id={`${id}-${k}`}>
            <rect x={x} y={y} width="34" height="34" />
          </clipPath>
        ))}
      </defs>
      {block && <rect width="100" height="100" rx="12" fill={block} />}
      <g fill="none" stroke={letters} strokeWidth="8.5" strokeLinejoin="round" strokeLinecap="butt">
        {(Object.keys(PATHS) as Array<keyof typeof PATHS>).map((k) => (
          <path key={k} clipPath={`url(#${id}-${k})`} d={PATHS[k]} />
        ))}
      </g>
      {living && (
        <>
          <path
            d="M50 4 V96 M4 50 H96"
            fill="none"
            stroke="var(--c-fjord)"
            strokeWidth="1.2"
            strokeLinecap="round"
            style={{ strokeDasharray: 240, ['--len' as string]: 240, animation: 'thread-draw 2.4s var(--ease-in-out) .2s both' }}
          />
          <circle cx="50" cy="50" r="3" fill="var(--c-fjord)" style={{ transformOrigin: '50px 50px', animation: 'node-pulse 2.4s ease-out 1.6s infinite' }} />
          <circle cx="50" cy="50" r="1.8" fill="var(--c-snow)" />
        </>
      )}
    </svg>
  );
}

/** Mark + "grta.ai" wordmark. The wordmark follows the text colour, so it works in both themes. */
export function Lockup({ size = 34, className, living = false }: { size?: number; className?: string; living?: boolean }) {
  return (
    <span className={cn('inline-flex items-center gap-2.5', className)}>
      <Mark size={size} living={living} />
      <span className="font-display font-bold tracking-tight" style={{ fontSize: size * 0.62, lineHeight: 1 }}>
        grta.ai
      </span>
    </span>
  );
}
